import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"Use Lab And The Asset Library","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/lab-viewer","contentType":"guide","prev":{"text":"Quick start","link":"/en/getting-started/quickstart"},"next":false},"headers":[],"relativePath":"en/guides/lab-viewer.md","filePath":"en/guides/lab-viewer.md"}'),r={name:"en/guides/lab-viewer.md"};function n(l,e,o,p,c,d){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="use-lab-and-the-asset-library" tabindex="-1">Use Lab And The Asset Library <a class="header-anchor" href="#use-lab-and-the-asset-library" aria-label="Permalink to &quot;Use Lab And The Asset Library&quot;">​</a></h1><p>Goal: inspect equipment in the application, import a local GLB and reopen it from the asset library. Lab uses the existing identity and shell; 3D code loads with the page.</p><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h2><p>From the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>. Sign in or register at <code>/register</code>; both login and registration land on Lab. <code>just dev</code> starts services and runs migrations against existing development data, not an isolated test environment.</p><ol><li>Expect the industrial microscope, HDR lighting and a grid.</li><li>Orbit, zoom and pan. Fit preserves the viewing direction and reset restores the original direction. Click the model to select it, or empty space to clear selection.</li><li>Select or drop a self-contained glTF 2.0 <code>.glb</code>; it is centered and framed while preserving its scale.</li><li>Search names or filenames in Asset library, open a model in Lab, or confirm removal of a local entry.</li><li>Invalid imports show feedback and preserve the previous usable model; a valid retry recovers.</li></ol><p>The catalog belongs to the current browser session. Reload or identity changes clear local files; the preset remains available. Legacy document and knowledge-base URLs retain their meaning. FPS, draw calls, triangles, object counts and available JS heap are observed live. GPU timing is not sampled and object counts do not measure GPU memory bytes.</p><p>Start at the <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/apps/web/src/app-examples.tsx" target="_blank" rel="noreferrer">assembly</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/packages/views/src/lab/app-example.tsx" target="_blank" rel="noreferrer">Lab contribution</a> and <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/packages/views/src/lab/lab-view.tsx" target="_blank" rel="noreferrer">viewer</a>. The <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/assets/README.md" target="_blank" rel="noreferrer">asset record</a> retains originals, runtime files and licenses.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/perf-bundle.mjs</span></span></code></pre></div><p>Page checks cover the catalog, navigation, import feedback and removal. WebGL, camera, selection and resource lifetime require browser verification. Background server logs must live outside the application&#39;s watched directory to avoid console/file-watch reload loops.</p><h2 id="historical-v1-preview" tabindex="-1">Historical v1 Preview <a class="header-anchor" href="#historical-v1-preview" aria-label="Permalink to &quot;Historical v1 Preview&quot;">​</a></h2><p>Use Node, pnpm, desktop Chrome and a local <code>.scratch/lab-viewer/v1/</code>. The local <code>preview/lab-viewer-v1</code> branch preserves the complete version at <code>9439a1de78c5433795d22a03e3e6086540832794</code>. It is outside the main branch&#39;s source tree. A main-only checkout cannot run these commands. The preview branch is currently local; check online availability after publication.</p><p>With the version directory present, run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:5190/prototype/lab-viewer" target="_blank" rel="noreferrer">http://127.0.0.1:5190/prototype/lab-viewer</a>. If the port is occupied, use Vite&#39;s reported address. No API or database is required and no production application data is written.</p><p>If the local branch exists but the directory is absent, create a separate worktree:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../lab-word-preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview/lab-viewer-v1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../lab-word-preview/.scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../lab-word-preview/.scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><h2 id="observe-a-complete-operation" tabindex="-1">Observe A Complete Operation <a class="header-anchor" href="#observe-a-complete-operation" aria-label="Permalink to &quot;Observe A Complete Operation&quot;">​</a></h2><ol><li>On first load, expect a microscope and environment lighting instead of a blank canvas.</li><li>Orbit, zoom and pan, then focus/reset. Select the equipment to inspect static information; click empty space to clear selection.</li><li>Select or drop a self-contained glTF 2.0 <code>.glb</code>. The new model is centered and framed automatically.</li><li>Import an invalid file or GLB with missing external resources. Expect explicit feedback and the previous usable model. A subsequent valid import should work.</li><li>Inspect FPS, draw calls, triangles and resource counts. JS heap and GPU timing differ from object counts; unavailable measurements are marked unavailable.</li></ol><p>Files stay in the current browser session without server upload. Refresh does not guarantee recovery of imports. v1 inspects one model at a time and has no placement editor.</p><h2 id="assets-and-evidence" tabindex="-1">Assets And Evidence <a class="header-anchor" href="#assets-and-evidence" aria-label="Permalink to &quot;Assets And Evidence&quot;">​</a></h2><p>The preset is Poly Haven&#39;s <a href="https://polyhaven.com/a/industrial_microscope" target="_blank" rel="noreferrer">Industrial Microscope</a>, by Lukas Walzer, CC0. The environment is <a href="https://polyhaven.com/a/studio_small_03" target="_blank" rel="noreferrer">Studio Small 03</a>, by Greg Zaal, CC0. Sources and runtime GLB/HDR files are preserved with the preview.</p><p>Prior Chromium/SwiftShader checks cover rendering, imports, selection, camera and recovery. Software-rendering FPS is not GPU acceptance, and preview bundle size is not production budget evidence. The <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/docs/ui/lab-viewer-experience.md" target="_blank" rel="noreferrer">experience record</a>documents scope and evidence.</p><p>Identity and template navigation are simulated, and the v1 visual experience is accepted. The user&#39;s correction makes Lab and Asset Library the main business navigation while retaining legacy knowledge routes. Production routing, import lifecycle and <a href="./../testing/feedback-loop">public validation</a>still await acceptance. See <a href="./../architecture/lab-word">product architecture</a>.</p><hr><p>Source version：<code>e080eb3aca90</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/docs/guides/lab-viewer.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,27)])])}const k=a(r,[["render",n]]);export{b as __pageData,k as default};
